import { test, expect } from '@playwright/test';

test.describe('Notification Auto-Dismiss Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should auto-dismiss notification after 5 seconds', async ({ page }) => {
    // Trigger a notification
    await page.getByRole('button', { name: /trigger notification/i }).click();

    // Verify notification is visible
    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Record the time when notification appears
    const startTime = Date.now();

    // Wait for notification to disappear
    await expect(notification).not.toBeVisible({ timeout: 6000 });

    // Verify it took approximately 5 seconds (with some tolerance)
    const elapsedTime = Date.now() - startTime;
    expect(elapsedTime).toBeGreaterThanOrEqual(4500);
    expect(elapsedTime).toBeLessThan(6500);
  });

  test('should dismiss multiple notifications sequentially after 5 seconds each', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: /trigger notification/i });

    // Trigger first notification
    await triggerButton.click();
    let notification = page.getByRole('alert').first();
    await expect(notification).toBeVisible();

    // Wait for first notification to dismiss
    await expect(notification).not.toBeVisible({ timeout: 6000 });

    // Trigger second notification
    await triggerButton.click();
    notification = page.getByRole('alert').first();
    await expect(notification).toBeVisible();

    // Wait for second notification to dismiss
    await expect(notification).not.toBeVisible({ timeout: 6000 });

    // Verify no notifications remain
    await expect(page.getByRole('alert')).toHaveCount(0);
  });

  test('should maintain auto-dismiss timer for stacked notifications', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: /trigger notification/i });

    // Trigger multiple notifications rapidly
    await triggerButton.click();
    await page.waitForTimeout(500);
    await triggerButton.click();
    await page.waitForTimeout(500);
    await triggerButton.click();

    // Verify all notifications are visible
    const notifications = page.getByRole('alert');
    await expect(notifications).toHaveCount(3);

    // Wait for all notifications to auto-dismiss
    await expect(notifications.first()).not.toBeVisible({ timeout: 6000 });
    await expect(notifications.nth(1)).not.toBeVisible({ timeout: 6000 });
    await expect(notifications.nth(2)).not.toBeVisible({ timeout: 6000 });

    // Verify all notifications are gone
    await expect(page.getByRole('alert')).toHaveCount(0);
  });

  test('should reset dismiss timer when notification is interacted with', async ({ page }) => {
    // Trigger a notification
    await page.getByRole('button', { name: /trigger notification/i }).click();

    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Wait 3 seconds (before auto-dismiss)
    await page.waitForTimeout(3000);

    // Interact with notification (e.g., hover or focus)
    await notification.hover();

    // Notification should still be visible after 5 more seconds from interaction
    await page.waitForTimeout(2000);
    await expect(notification).toBeVisible();

    // Wait for the remaining time to auto-dismiss
    await expect(notification).not.toBeVisible({ timeout: 4000 });
  });

  test('should display correct notification content before auto-dismiss', async ({ page }) => {
    const testMessage = 'Test notification message';

    // Trigger notification with specific message
    await page.getByRole('button', { name: /trigger notification/i }).click();

    const notification = page.getByRole('alert');
    await expect(notification).toBeVisible();

    // Verify notification contains expected text
    await expect(notification).toContainText(/notification/i);

    // Verify notification is still visible and has content
    const notificationText = await notification.textContent();
    expect(notificationText).toBeTruthy();
    expect(notificationText?.length).toBeGreaterThan(0);

    // Wait for auto-dismiss
    await expect(notification).not.toBeVisible({ timeout: 6000 });
  });

  test('should handle rapid successive notification triggers with proper auto-dismiss', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: /trigger notification/i });

    // Rapidly trigger notifications
    for (let i = 0; i < 5; i++) {
      await triggerButton.click();
      await page.waitForTimeout(200);
    }

    // Verify multiple notifications are visible
    const notifications = page.getByRole('alert');
    const initialCount = await notifications.count();
    expect(initialCount).toBeGreaterThan(0);

    // Wait for all to auto-dismiss
    await page.waitForTimeout(6000);

    // Verify all notifications have been dismissed
    await expect(page.getByRole('alert')).toHaveCount(0);
  });
});
